/*
 * Retired service worker (was generated by astrojs-service-worker).
 * This file must stay at /service-worker.js: returning visitors still run the
 * old cache-first worker, which keeps serving the stale precache unless this
 * script replaces it. It caches nothing and only clears old caches, so the
 * PWA worker (sw.js, registered by src/pwa.ts) can take over the scope.
 * Safe to delete a few months after the switch.
 */
self.addEventListener('install', () => {
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys()
      await Promise.all(names.map((name) => caches.delete(name)))
      await self.clients.claim()
    })(),
  )
})
